args.command:
cd /tmp/probe
echo 'hello world' | /workspace/executable --stdout-detection force-tty --only-matching 'o' 2>/dev/null | od -c
echo ===
echo 'hello world' | /workspace/executable --stdout-detection force-pipe --only-matching 'o' 2>/dev/null | od -c
echo ===
script -qec "printf 'def f():\n    pass\n' | /workspace/executable --python def" /dev/null | od -c | head
echo ===
# does TTY action output get colors/diff?
script -qec "echo 'hello world' | /workspace/executable 'o' -- 'X'" /dev/null | od -c | head

cd /tmp/probe
script -qec "printf 'foo bar\nbaz qux\n' | /workspace/executable --only-matching 'foo'" /dev/null | od -c
echo ===
script -qec "printf 'foo bar\nbaz qux\n' | /workspace/executable --line-numbers 'foo'" /dev/null | od -c
echo ===
script -qec "echo 'hello world' | /workspace/executable --only-matching 'o' -- 'X'" /dev/null | od -c
echo ===
script -qec "echo 'hello world' | /workspace/executable --line-numbers 'o' --upper" /dev/null | od -c
echo ===
# NO_COLOR / TERM influence?
echo 'hello world' | /workspace/executable --stdout-detection force-tty --line-numbers 'o' 2>/dev/null | od -c

cd /tmp/probe
script -qec "printf 'foo bar\nbaz qux\n' | /workspace/executable --only-matching 'foo' -- 'X'" /dev/null | od -c
echo ===
printf 'foo bar\nbaz qux\n' | /workspace/executable --only-matching 'foo' -- 'X' 2>/dev/null | od -c
echo ===
# ranges with action: are ranges pre- or post-action? test replacement changing length before match
printf 'aaa bbb\n' | /workspace/executable --only-matching 'a+|b+' -- 'X' 2>/dev/null
echo ===
# delete with only-matching
printf 'foo bar foo\n' | /workspace/executable --only-matching -d 'foo' 2>&1; echo "EXIT=$?"
echo ===
# multi-line match spanning newline: does only-matching show it?
printf 'ab\ncd\n' | /workspace/executable --only-matching 'b\nc' 2>/dev/null | od -c
echo ===
printf 'ab\ncd\n' | /workspace/executable --line-numbers 'b\nc' 2>/dev/null | od -c

cd /tmp/probe
printf 'foo bar foo\n' | /workspace/executable -d 'foo' 2>/dev/null | od -c
echo ===
printf 'foo bar foo\n' | /workspace/executable --line-numbers -d 'foo' 2>/dev/null | od -c
echo ===
script -qec "printf 'foo bar foo\n' | /workspace/executable --only-matching -d 'foo'" /dev/null | od -c
echo ===
# delete with no scope (default .*) - help says required
printf 'foo\n' | /workspace/executable -d 2>&1; echo "EXIT=$?"
echo ===
# squeeze
printf 'fooooo bar\n' | /workspace/executable -s 'o' 2>/dev/null | od -c
echo ===
# delete + other action combo
printf 'foo\n' | /workspace/executable -d --upper 'foo' 2>&1; echo "EXIT=$?"
echo ===
printf 'foo\n' | /workspace/executable -d 'foo' -- 'X' 2>&1; echo "EXIT=$?"
echo ===
printf 'foo\n' | /workspace/executable -s -d 'o' 2>&1; echo "EXIT=$?"

cd /tmp/probe
printf 'foo\n' | /workspace/executable --only-matching 'o' 2>/dev/null | od -c
echo ===
printf 'ab\ncd\n' | /workspace/executable --only-matching 2>/dev/null | od -c
echo ===
printf 'ab\ncd\n' | /workspace/executable --only-matching '\n' 2>/dev/null | od -c
echo ===
printf 'ab\n\ncd\n' | /workspace/executable --line-numbers 'c' 2>/dev/null | od -c
echo ===
# delete + only-matching piped: empty ranges?
printf 'foo bar\n' | /workspace/executable --only-matching -d 'foo' 2>/dev/null | od -c
echo ===
printf 'foo bar\n' | /workspace/executable --line-numbers -d 'foo' 2>/dev/null | od -c

cd /tmp/probe
printf 'x\n' | /workspace/executable 'a{2,1}' -- 'X' 2>&1 | od -c | tail -6
echo ===
printf 'x\n' | /workspace/executable '[z-a]' -- 'X' 2>&1
echo ===
printf 'x\n' | /workspace/executable '(?-u)a' -- 'X' 2>&1
echo ===
printf 'x\n' | /workspace/executable '(?P<1>a)' -- 'X' 2>&1
echo ===
printf 'x\n' | /workspace/executable '(a)(a)' -- 'X' 2>&1; echo "EXIT=$?"
printf 'xaa\n' | /workspace/executable '(?P<n>a)(?P<n>a)' -- 'X' 2>&1; echo "EXIT=$?"
